35	export const loader = async ({ request }: LoaderFunctionArgs) => {
36	  const { session } = await authenticate.admin(request);
37	  const shop = session.shop;
38	
39	  let config = await db.widgetConfig.findUnique({ where: { shop } });
40	
41	  if (!config) {
42	    config = await db.widgetConfig.create({ data: { shop } });
43	  }
44	
45	  const subscription = await getShopSubscription(shop);
46	
47	  return { config, subscription };
48	};
