102	export const action = async ({ request }: ActionFunctionArgs) => {
103	  try {
104	    const { session, admin } = await authenticate.admin(request);
105	    const shop = session.shop;
106	    const formData = await request.formData();
107	    const intent = formData.get("intent");
108	
109	    if (intent === "save") {
110	      const data = {
111	        position: String(formData.get("position") || "inline"),
112	        primaryColor: String(formData.get("primaryColor") || "#008060"),
113	        successColor: String(formData.get("successColor") || "#008060"),
114	        errorColor: String(formData.get("errorColor") || "#D72C0D"),
115	        backgroundColor: String(formData.get("backgroundColor") || "#FFFFFF"),
116	        textColor: String(formData.get("textColor") || "#202223"),
117	        heading: String(formData.get("heading") || "Check Delivery Availability"),
118	        placeholder: String(formData.get("placeholder") || "Enter your zip code"),
119	        buttonText: String(formData.get("buttonText") || "Check"),
120	        successMessage: String(
121	          formData.get("successMessage") ||
122	            "Great news! We deliver to your area.",
123	        ),
124	        errorMessage: String(
125	          formData.get("errorMessage") ||
126	            "Sorry, we don't deliver to this area yet.",
127	        ),
128	        notFoundMessage: String(
129	          formData.get("notFoundMessage") ||
130	            "We currently do not ship to this ZIP code.",
131	        ),
132	        showEta: formData.get("showEta") === "true",
133	        showZone: formData.get("showZone") === "true",
134	        showWaitlistOnFailure: formData.get("showWaitlistOnFailure") === "true",
135	        showCod: formData.get("showCod") === "true",
136	        showReturnPolicy: formData.get("showReturnPolicy") === "true",
137	        showCutoffTime: formData.get("showCutoffTime") === "true",
138	        showDeliveryDays: formData.get("showDeliveryDays") === "true",
139	        showDeliveryDate: formData.get("showDeliveryDate") === "true",
140	        showCountdown: formData.get("showCountdown") === "true",
141	        showDeliveryFee: formData.get("showDeliveryFee") === "true",
142	        blockCartOnInvalid: formData.get("blockCartOnInvalid") === "true",
143	        blockCheckoutInCart: formData.get("blockCheckoutInCart") === "true",
144	        showSocialProof: formData.get("showSocialProof") === "true",
145	        lockButtonsUntilZipCheck: formData.get("lockButtonsUntilZipCheck") === "true",
146	        borderRadius: String(formData.get("borderRadius") || "8"),
147	        customCss: String(formData.get("customCss") || "").slice(0, MAX_CUSTOM_CSS_LENGTH) || null,
148	      };
149	
150	      // Server-side plan gating: strip premium fields the shop's plan doesn't allow
151	      const subscription = await getShopSubscription(shop);
152	      const limits = PLAN_LIMITS[subscription.planTier];
153	      if (!limits.widgetFullCustom) {
154	        data.primaryColor = "#008060";
155	        data.successColor = "#008060";
156	        data.errorColor = "#D72C0D";
157	        data.backgroundColor = "#FFFFFF";
158	        data.textColor = "#202223";
159	        data.position = "inline";
160	      }
161	      if (!limits.showEtaCodReturn) {
162	        data.showEta = false;
163	        data.showZone = false;
164	        data.showCod = false;
165	        data.showReturnPolicy = false;
166	        data.showCutoffTime = false;
167	        data.showDeliveryDays = false;
168	        data.showDeliveryDate = false;
169	        data.showCountdown = false;
170	        data.showDeliveryFee = false;
171	      }
172	      if (!limits.customCss) {
173	        data.customCss = null;
174	      }
175	      if (!limits.cartBlocking) {
176	        data.blockCartOnInvalid = false;
177	        data.blockCheckoutInCart = false;
178	        // lockButtonsUntilZipCheck is allowed on all plans — do not strip it
179	      }
180	
181	      await db.widgetConfig.upsert({
182	        where: { shop },
183	        create: { shop, ...data },
184	        update: data,
185	      });
186	
187	      await syncConfigMetafield(admin, data);
188	
189	      return { success: true };
190	    }
191	
192	    if (intent === "reset") {
193	      const resetData = {
194	        position: "inline",
195	        primaryColor: "#008060",
196	        successColor: "#008060",
197	        errorColor: "#D72C0D",
198	        backgroundColor: "#FFFFFF",
199	        textColor: "#202223",
200	        heading: "Check Delivery Availability",
201	        placeholder: "Enter your zip code",
202	        buttonText: "Check",
203	        successMessage: "Great news! We deliver to your area.",
204	        errorMessage: "Sorry, we don't deliver to this area yet.",
205	        notFoundMessage: "We currently do not ship to this ZIP code.",
206	        showEta: true,
207	        showZone: false,
208	        showWaitlistOnFailure: false,
209	        showCod: true,
210	        showReturnPolicy: true,
211	        showCutoffTime: true,
212	        showDeliveryDays: true,
213	        showDeliveryDate: true,
214	        showCountdown: true,
215	        showDeliveryFee: true,
216	        blockCartOnInvalid: false,
217	        blockCheckoutInCart: false,
218	        showSocialProof: true,
219	        lockButtonsUntilZipCheck: true,
220	        borderRadius: "8",
221	        customCss: null,
222	      };
223	
224	      await db.widgetConfig.upsert({
225	        where: { shop },
226	        create: { shop },
227	        update: resetData,
228	      });
229	
230	      await syncConfigMetafield(admin, resetData);
231	
232	      return { success: true, action: "reset" };
233	    }
234	
235	    return null;
236	  } catch {
237	    return new Response(JSON.stringify({ error: "Failed to save widget settings." }), {
238	      status: 500,
239	      headers: { "Content-Type": "application/json" },
240	    });
241	  }
