307	// ── Scope custom CSS for admin preview — prefix selectors with #wid ─────────
308	// Handles @keyframes/@font-face (pass-through), @media (recursive scoping),
309	// and regular selectors (prefixed with container ID).
310	function scopeAdminCss(rawCss: string | null | undefined, wid: string): string {
311	  if (!rawCss) return "";
312	  // Sanitize the same way the public API does (mirrors api.widget-config.tsx)
313	  const css = rawCss
314	    .replace(/<style\b[^>]*>/gi, "")
315	    .replace(/<\/style>/gi, "")
316	    .replace(/@import\b[^;]*(;|$)/gi, "")
317	    .replace(/\bexpression\s*\(/gi, "")
318	    .replace(/url\s*\(\s*['"]?\s*javascript\s*:/gi, "url(")
319	    .replace(/url\s*\(\s*['"]?\s*data\s*:/gi, "url(");
320	  let result = "";
321	  let i = 0;
322	  while (i < css.length) {
323	    // Skip whitespace
324	    while (i < css.length && /\s/.test(css[i])) { result += css[i]; i++; }
325	    if (i >= css.length) break;
326	    // Handle at-rules
327	    if (css[i] === "@") {
328	      let atRule = "";
329	      let j = i;
330	      while (j < css.length && css[j] !== "{" && css[j] !== ";") { atRule += css[j]; j++; }
331	      const atName = atRule.trim().toLowerCase();
332	      // @keyframes and @font-face: pass through without scoping
333	      if (atName.startsWith("@keyframes") || atName.startsWith("@font-face")) {
334	        result += atRule;
335	        if (j < css.length && css[j] === "{") {
336	          let depth = 1; result += css[j]; j++;
337	          while (j < css.length && depth > 0) {
338	            if (css[j] === "{") depth++;
339	            if (css[j] === "}") depth--;
340	            result += css[j]; j++;
341	          }
342	        }
343	        i = j; continue;
344	      }
345	      // @media: recursively scope inner rules
346	      if (atName.startsWith("@media")) {
347	        result += atRule;
348	        if (j < css.length && css[j] === "{") {
349	          result += "{"; j++;
350	          let depth = 1; let inner = "";
351	          while (j < css.length && depth > 0) {
352	            if (css[j] === "{") depth++;
353	            if (css[j] === "}") depth--;
354	            if (depth > 0) inner += css[j];
355	            j++;
356	          }
357	          result += scopeAdminCss(inner, wid);
358	          result += "}";
359	        }
360	        i = j; continue;
361	      }
362	    }
363	    // Regular rule: grab selector, prefix with #wid
364	    let sel = "";
365	    let body = "";
366	    while (i < css.length && css[i] !== "{") { sel += css[i]; i++; }
367	    if (i < css.length) i++; // skip {
368	    let depth = 1;
369	    while (i < css.length && depth > 0) {
370	      if (css[i] === "{") depth++;
371	      if (css[i] === "}") depth--;
372	      if (depth > 0) body += css[i];
373	      i++;
374	    }
375	    if (sel.trim()) {
376	      const prefixed = sel.split(",").map(s => {
377	        s = s.trim();
378	        return s ? "#" + wid + " " + s : "";
379	      }).filter(Boolean).join(", ");
380	      result += prefixed + " {" + body + "}";
381	    }
382	  }
383	  return result;
384	}
