453	function buildWidgetCss(wid: string, cfg: WidgetConfig): string {
454	  const W = "#" + wid;
455	  const p = cfg.primaryColor;
456	  const s = cfg.successColor;
457	  const e = cfg.errorColor;
458	  const btnRadius = (cfg.borderRadius || "10") + "px";
459	  const base =
460	    "@keyframes zcc-slide-in{from{opacity:0;transform:translateY(10px)}to{opacity:1;transform:translateY(0)}}" +
461	    "@keyframes zcc-scale-in{from{transform:scale(0.92);opacity:0}to{transform:scale(1);opacity:1}}" +
462	    "@keyframes zcc-pulse-ring{0%{transform:scale(1);opacity:.5}50%{transform:scale(1.2);opacity:0}100%{transform:scale(1.2);opacity:0}}" +
463	    W + "{background:" + cfg.backgroundColor + ";color:" + cfg.textColor + ";padding:16px;border:none;border-radius:12px;box-shadow:0 2px 12px rgba(0,0,0,0.08);max-width:480px;width:100%;font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,sans-serif;box-sizing:border-box}" +
464	    W + " *{box-sizing:border-box}" +
465	    W + " .zcc-heading{font-size:15px;font-weight:700;letter-spacing:-0.01em;margin:0;color:" + cfg.textColor + ";display:flex;align-items:center;gap:8px;padding-bottom:12px;border-bottom:1px solid rgba(0,0,0,0.06);margin-bottom:12px}" +
466	    W + " .zcc-heading-icon{display:inline-flex;align-items:center;justify-content:center;width:28px;height:28px;border-radius:50%;background:linear-gradient(135deg," + p + "18," + p + "08);flex-shrink:0}" +
467	    W + " .zcc-heading-icon svg{width:14px;height:14px}" +
468	    W + " .zcc-search-bar{display:flex;flex-direction:row;gap:10px;align-items:stretch}" +
469	    W + " .zcc-input{flex:1;min-width:0;padding:12px 16px;font-size:14px;border:1.5px solid #e0e0e0;border-radius:" + btnRadius + ";outline:none;background:#fafbfb;color:" + cfg.textColor + ";transition:border-color 0.2s,box-shadow 0.2s}" +
