448	  // ── Countdown timer functions ─────────────────────────────────────────────────
449	  function getCountdownData(cutoffTime) {
450	    if (!cutoffTime) return null;
451	    var parts = cutoffTime.split(':');
452	    var cutoffHr = parseInt(parts[0], 10);
453	    var cutoffMin = parseInt(parts[1] || '0', 10);
454	    var now = new Date();
455	    var cutoff = new Date();
456	    cutoff.setHours(cutoffHr, cutoffMin, 0, 0);
457	    var diff = cutoff - now;
458	    if (diff <= 0) return { passed: true, hours: 0, minutes: 0 };
459	    var hours = Math.floor(diff / 3600000);
460	    var minutes = Math.floor((diff % 3600000) / 60000);
461	    return { passed: false, hours: hours, minutes: minutes };
462	  }
