473	      if (totalMinutes > 180) colorClass = 'zcc-countdown--green';
474	      else if (totalMinutes > 60) colorClass = 'zcc-countdown--amber';
475	      else colorClass = 'zcc-countdown--red';
476	      text = 'Order within <strong>' + cd.hours + 'h ' + cd.minutes + 'm</strong> for same-day dispatch';
